window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4f1d0e7ebd03b5b3"]={"versions": [{"id": "FIG-4f1d0e7ebd03b5b3", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm aus der AUTOSAR-Spezifikation des CAN State Managers (CanSM, Kommunikationsstapel der Classic Platform). Dargestellt ist der synchrone Interaktionsausschnitt während der Bus-Off-Recovery zur Aktivierung des TX-Pfads auf PDU-Ebene über das CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte BSW-Module mit Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>CanSM::CanSM</code> («module»): Aufrufende Entität / Steuerung der Bus-Off-Wiederherstellung.\n</li><li><code>CanIf::CanIf</code> («module»): Aufgerufene Treiberschnittstelle.\n</li></ul>\n<p class=\"fig-p\">Schnittstellenfunktion:</p>\n<ul class=\"fig-list\"><li><code>CanIf_SetPduMode(CanController, PduModeRequest:=CANIF_SET_TX_ONLINE) : Std_ReturnType</code>: Synchroner Funktionsaufruf mit den Parametern <code>CanController</code> und <code>PduModeRequest</code> (Wert <code>CANIF_SET_TX_ONLINE</code>) sowie dem Rückgabetyp <code>Std_ReturnType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Innerhalb eines kombinierten Interaktionsfragments <code>loop</code> mit der Guard-Bedingung „For every CAN controller assinged to this CAN network handle“ führt CanSM eine Iteration über alle dem betroffenen Netzwerk-Handle zugeordneten CAN-Controller aus:</p>\n<ol class=\"fig-list\"><li>CanSM sendet einen synchronen Aufruf <code>CanIf_SetPduMode</code> mit <code>PduModeRequest:=CANIF_SET_TX_ONLINE</code> an CanIf.\n</li><li>CanIf verarbeitet den Aufruf während des Ausführungsfokus (Activation Bar).\n</li><li>CanIf gibt die synchrone Antwort mit Statuswert (<code>Std_ReturnType</code>) an CanSM zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm spezifiziert das Soll-Verhalten des CanSM bei der Reaktivierung des Sendebetriebs nach einem Bus-Off. Entwickler müssen sicherstellen, dass bei Netzwerken mit mehreren zugeordneten Controllern der PDU-Modus für jeden Controller synchron auf <code>CANIF_SET_TX_ONLINE</code> geschaltet und der Rückgabewert (<code>Std_ReturnType</code>) ausgewertet wird. Hinweis auf Schreibfehler im Standard-Guard-Text: „assinged“ statt „assigned“.</p>"}, {"id": "FIG-a134f4d364d54a7c", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm aus der AUTOSAR-Spezifikation des CAN State Managers (CanSM, Kommunikationsstapel der Classic Platform). Dargestellt ist der synchrone Interaktionsausschnitt während der Bus-Off-Recovery zur Aktivierung des TX-Pfads auf PDU-Ebene über das CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte BSW-Module mit Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>CanSM::CanSM</code> («module»): Aufrufende Entität / Steuerung der Bus-Off-Wiederherstellung.\n</li><li><code>CanIf::CanIf</code> («module»): Aufgerufene Treiberschnittstelle.\n</li></ul>\n<p class=\"fig-p\">Schnittstellenfunktion:</p>\n<ul class=\"fig-list\"><li><code>CanIf_SetPduMode(CanController, PduModeRequest:=CANIF_SET_TX_ONLINE) : Std_ReturnType</code>: Synchroner Funktionsaufruf mit den Parametern <code>CanController</code> und <code>PduModeRequest</code> (Wert <code>CANIF_SET_TX_ONLINE</code>) sowie dem Rückgabetyp <code>Std_ReturnType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Innerhalb eines kombinierten Interaktionsfragments <code>loop</code> mit der Guard-Bedingung „For every CAN controller assinged to this CAN network handle“ führt CanSM eine Iteration über alle dem betroffenen Netzwerk-Handle zugeordneten CAN-Controller aus:</p>\n<ol class=\"fig-list\"><li>CanSM sendet einen synchronen Aufruf <code>CanIf_SetPduMode</code> mit <code>PduModeRequest:=CANIF_SET_TX_ONLINE</code> an CanIf.\n</li><li>CanIf verarbeitet den Aufruf während des Ausführungsfokus (Activation Bar).\n</li><li>CanIf gibt die synchrone Antwort mit Statuswert (<code>Std_ReturnType</code>) an CanSM zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm spezifiziert das Soll-Verhalten des CanSM bei der Reaktivierung des Sendebetriebs nach einem Bus-Off. Entwickler müssen sicherstellen, dass bei Netzwerken mit mehreren zugeordneten Controllern der PDU-Modus für jeden Controller synchron auf <code>CANIF_SET_TX_ONLINE</code> geschaltet und der Rückgabewert (<code>Std_ReturnType</code>) ausgewertet wird. Hinweis auf Schreibfehler im Standard-Guard-Text: „assinged“ statt „assigned“.</p>"}], "trans": [{"from": "FIG-4f1d0e7ebd03b5b3", "to": "FIG-a134f4d364d54a7c", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
